#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Import the pinned GLES graph and HWC pair; never download other trees."""
import argparse
import hashlib
import json
import re
import shutil
import subprocess
from pathlib import Path

PINS = {
    "vendor-mithorium": "e264bd19f6158e9882efa1d7afe28e34bfd8ee4d",
    "mithorium": "2639cd7377cbd6b6ecf6f5317637c3faca96f86c",
    "Mi8937": "1d087f13f1027de6b110ae3f2a24f27de5d841a8",
}
LIBRARIES = [
    "egl/eglSubDriverAndroid.so", "egl/libEGL_adreno.so",
    "egl/libGLESv1_CM_adreno.so", "egl/libGLESv2_adreno.so",
    "libgsl.so", "libadreno_utils.so", "libllvm-glnext.so", "libCB.so",
]
DISPLAY_LIBRARIES = {
    "libsdmextension.so": "c9fef375b7425dc619e4a107322401f58d7557f8504ef496e7e4f8ced76a8d66",
    "libscalar.so": "25137b1b2b2ce0c76f4641062b9805b2d9a340b617c23154c592542e7587f4ad",
}
DISPLAY_NEEDED = ["libsdmutils.so", "libc++.so", "libc.so", "libm.so", "libdl.so"]
FIRMWARE = {
    "a300_pfp.fw": "b6e66400d46d52dc343d370b94362d564a765994bda47dc026961dd47a9ca7a9",
    "a300_pm4.fw": "f78c57e879e96a2c0ceeea31dbd30f7f1d4526f9c876e80481c654f08daaecd3",
}
SOURCE_MODULES = {
    "libc": "bionic/libc/Android.bp", "libm": "bionic/libm/Android.bp",
    "libdl": "bionic/libdl/Android.bp", "libcutils": "system/core/libcutils/Android.bp",
    "liblog": "system/logging/liblog/Android.bp", "libz": "external/zlib/Android.bp",
    "libsync": "system/core/libsync/Android.bp", "libutils": "system/core/libutils/Android.bp",
    "libhardware": "hardware/libhardware/Android.bp",
    "libvndksupport": "system/core/libvndksupport/Android.bp",
    "libc++": "prebuilts/clang/host/linux-x86/Android.bp",
    "libsdmutils": "hardware/qcom-caf/msm8953/display/sdm/libs/utils/Android.bp",
}
HOOKS = [
    "compute_aligned_width_and_height", "compute_fmt_aligned_width_and_height",
    "compute_surface_padding", "compute_compressedfmt_aligned_width_and_height",
    "isUBWCSupportedByGpu", "get_gpu_pixel_alignment", "isSecureContextSupportedByGpu",
    "adreno_get_metadata_blob_size", "adreno_init_memory_layout",
    "adreno_get_aligned_gpu_buffer_size",
]

def run(*args):
    return subprocess.check_output(args, text=True)

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def inspect(path):
    data = path.read_bytes()
    assert data[:4] == b"\x7fELF" and data[5] == 1, path
    machine = int.from_bytes(data[18:20], "little")
    expected = (1, 40) if "/lib/" in path.as_posix() else (2, 183)
    assert (data[4], machine) == expected, (path, data[4], machine)
    dynamic = run("readelf", "-d", str(path))
    needed = re.findall(r"\(NEEDED\).*\[([^]]+)\]", dynamic)
    soname = re.findall(r"\(SONAME\).*\[([^]]+)\]", dynamic)
    assert soname == [path.name], (path, soname)
    symbols = run("readelf", "--dyn-syms", "--wide", str(path))
    exported = {line.split()[-1].split("@")[0] for line in symbols.splitlines()
                if " GLOBAL " in line and " UND " not in line}
    return {"elf_class": data[4] * 32, "machine": machine, "soname": soname[0],
            "needed": needed, "allocator_hooks": sorted(set(HOOKS) & exported)}

def generate_bp(receipt):
    text = ['// SPDX-License-Identifier: Apache-2.0',
            '// Generated by import-graphics.py from pinned unmodified binaries.',
            'soong_namespace { imports: ["hardware/qcom-caf/msm8953"], }',
            'package { default_applicable_licenses: ["t380-adreno-proprietary-license"], }',
            'license { name: "t380-adreno-proprietary-license", license_kinds: ["legacy_proprietary"], license_text: ["NOTICE"], }']
    for lib in LIBRARIES:
        name = Path(lib).stem
        dep32 = receipt["files"][f"proprietary/vendor/lib/{lib}"]["needed"]
        dep64 = receipt["files"][f"proprietary/vendor/lib64/{lib}"]["needed"]
        assert dep32 == dep64, (lib, dep32, dep64)
        dependencies = ", ".join(json.dumps(Path(d).stem) for d in dep32)
        text.append(f'''cc_prebuilt_library_shared {{
    name: "{name}",
    owner: "qualcomm",
    strip: {{ none: true, }},
    target: {{
        android_arm: {{ srcs: ["proprietary/vendor/lib/{lib}"], }},
        android_arm64: {{ srcs: ["proprietary/vendor/lib64/{lib}"], }},
    }},
    compile_multilib: "both",
    check_elf_files: true,
    shared_libs: [{dependencies}],
    system_shared_libs: [],
    prefer: true,
    soc_specific: true,
''' + ('    relative_install_path: "egl",\n' if lib.startswith("egl/") else "") + '}')
    for filename in DISPLAY_LIBRARIES:
        name = Path(filename).stem
        dependencies = ", ".join(json.dumps(Path(d).stem) for d in DISPLAY_NEEDED)
        text.append(f'''cc_prebuilt_library_shared {{
    name: "{name}",
    owner: "qualcomm",
    strip: {{ none: true, }},
    srcs: ["proprietary/vendor/lib64/{filename}"],
    compile_multilib: "64",
    check_elf_files: true,
    shared_libs: [{dependencies}],
    system_shared_libs: [],
    prefer: true,
    soc_specific: true,
}}''')
    for abi in ("lib", "lib64"):
        for lib in ("libEGL_adreno", "libGLESv2_adreno"):
            text.append(f'''install_symlink {{
    name: "t380-{abi}-{lib}-root-link",
    soc_specific: true,
    installed_location: "{abi}/{lib}.so",
    symlink_target: "/vendor/{abi}/egl/{lib}.so",
    required: ["{lib}"],
}}''')
    for firmware in FIRMWARE:
        text.append(f'''prebuilt_firmware {{
    name: "t380-{firmware}",
    src: "proprietary/vendor/firmware/{firmware}",
    filename: "{firmware}",
    soc_specific: true,
}}''')
    return "\n\n".join(text) + "\n"

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--references", required=True, type=Path)
    ap.add_argument("--lineage", required=True, type=Path)
    ap.add_argument("--firmware", required=True, type=Path)
    ap.add_argument("--output", type=Path, default=Path(__file__).resolve().parent)
    args = ap.parse_args()
    out = args.output.resolve()
    out.mkdir(parents=True, exist_ok=True)
    for repo, pin in PINS.items():
        actual = run("git", "-C", str(args.references / repo), "rev-parse", "HEAD").strip()
        assert actual == pin, (repo, actual, pin)
    donor = args.references / "vendor-mithorium"
    entries = (args.references / "mithorium/proprietary-files-qc-vndr.txt").read_text()
    receipt = {"pins": PINS, "files": {}, "source_modules": SOURCE_MODULES,
               "limitations": ["Static module-name and ELF closure only; vendor variants, undefined symbols, linker namespaces, allocator handle ABI, KGSL ioctls and rendering require product build/device tests."]}
    for abi in ("lib", "lib64"):
        for lib in LIBRARIES:
            relative = f"proprietary/vendor/{abi}/{lib}"
            assert f"-vendor/{abi}/{lib};" in entries, relative
            original = donor / relative
            expected = run("git", "-C", str(donor), "rev-parse", f"HEAD:{relative}").strip()
            actual = run("git", "-C", str(donor), "hash-object", str(original)).strip()
            assert actual == expected, (relative, "donor blob modified")
            dest = out / relative
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(original, dest)
            receipt["files"][relative] = {"sha256": sha(dest), "git_blob": expected,
                "bytes": dest.stat().st_size, **inspect(dest)}
    for filename, digest in DISPLAY_LIBRARIES.items():
        relative = f"proprietary/vendor/lib64/{filename}"
        assert f"-vendor/lib64/{filename};" in entries, relative
        original = donor / relative
        expected = run("git", "-C", str(donor), "rev-parse", f"HEAD:{relative}").strip()
        actual = run("git", "-C", str(donor), "hash-object", str(original)).strip()
        assert actual == expected and sha(original) == digest, (relative, "donor blob changed")
        dest = out / relative
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(original, dest)
        details = inspect(dest)
        assert details["needed"] == DISPLAY_NEEDED, (relative, details["needed"])
        receipt["files"][relative] = {"sha256": digest, "git_blob": expected,
            "bytes": dest.stat().st_size, **details}
    library_names = {Path(lib).stem for lib in LIBRARIES}
    library_names.update(Path(lib).stem for lib in DISPLAY_LIBRARIES)
    for entry in receipt["files"].values():
        for dep in entry["needed"]:
            module = Path(dep).stem
            assert module in library_names or module in SOURCE_MODULES, dep
            if module in SOURCE_MODULES:
                bp = args.lineage / SOURCE_MODULES[module]
                assert re.search(r'name:\s*"' + re.escape(module) + r'"', bp.read_text()), (module, bp)
    for abi in ("lib", "lib64"):
        hooks = receipt["files"][f"proprietary/vendor/{abi}/libadreno_utils.so"]["allocator_hooks"]
        assert set(hooks) == set(HOOKS), hooks
    for firmware, digest in FIRMWARE.items():
        src = args.firmware / firmware
        assert sha(src) == digest, src
        dest = out / "proprietary/vendor/firmware" / firmware
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(src, dest)
        receipt["files"][dest.relative_to(out).as_posix()] = {
            "sha256": digest, "bytes": dest.stat().st_size, "source": "stock SM-T380 artifacts/gpu-firmware"}
    (out / "SHA256SUMS").write_text("".join(f'{item["sha256"]}  {path}\n' for path, item in sorted(receipt["files"].items())))
    (out / "graphics-receipt.json").write_text(json.dumps(receipt, indent=2) + "\n")
    (out / "Android.bp").write_text(generate_bp(receipt))
    subprocess.run([str(args.lineage / "prebuilts/build-tools/linux-x86/bin/bpfmt"),
                    "-w", str(out / "Android.bp")], check=True)
    print(f"PASS: 16 pinned ARM/AArch64 GLES libraries, 2 pinned ARM64 display libraries, 2 stock firmwares; DT_NEEDED module closure, SONAME and 10 allocator hooks per ABI; output={out}")

if __name__ == "__main__":
    main()
